import { useState } from "react";
export default function Form11() {
  const [form, setform] = useState({ name: "", email: "" });
  return (
    <>
      <form>
        <div className="div1">
          <div>
            <label> name</label>
            <input value={form.name} 
            onChange={(value)=>{
              setform()
            }}/>
          </div>
          <div>
            <label> email</label>
            <input value={form.email}/>
          </div>
        </div>
        <button className="btn">sumbet</button>
      </form>
    </>
  );
}
